{"hypotheses": [
  {
    "name": "Intangible Enhancement in Capital-Constrained Firms",
    "mechanism": "Firms with high R&D over market cap (RD) but low external financing (XFIN) may be constrained in capital, so their intangible investments are more selective and thus higher quality. Weighting these two primitives captures firms that maximize intangible efficiency, yielding a premium not captured by each factor alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RD"},
        {"weight": 1.0, "primitive": "IntanCFP"},
        {"weight": -0.5, "primitive": "XFIN"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "RD", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Customer Momentum with Organizational Capital",
    "mechanism": "Firms benefiting from positive customer momentum (iomom_cust) and strong organizational capital (OrgCap) may experience reinforcing effects, as sticky customer gains amplify when supported by robust internal processes, but this is distinct from typical momentum or quality blends.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 0.5, "primitive": "OrgCap"},
        {"weight": -0.5, "primitive": "LRreversal"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "OrgCap", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.78,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Analyst Disagreement and Market Microstructure",
    "mechanism": "Stocks with both high EPS forecast dispersion (ForecastDispersion) and wide bid-ask spreads (BidAskSpread) often reflect uncertainty and information frictions. Combining these targets mispricings not captured by either alone, as both investor disagreement and illiquidity amplify inefficiency.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": 1.0, "primitive": "BidAskSpread"},
        {"weight": -0.5, "primitive": "ExchSwitch"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "BidAskSpread", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.68,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Operating Leverage with Deferred Revenue Growth",
    "mechanism": "Firms exhibiting both high operating leverage (OPLeverage) and rising deferred revenues (DelDRC) are positioned for outsized profit expansion when demand surprises to the upside, especially in environments with term spread inversion when risk appetite is low.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OPLeverage"},
        {"weight": 1.0, "primitive": "DelDRC"},
        {"weight": -0.5, "primitive": "BookLeverage"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "OPLeverage", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.63,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Post-IPO Age and Intangible Investment Differential",
    "mechanism": "Younger post-IPO firms with higher R&D ability (R&DAbility) but shorter seasoning (AgeIPO) and lower tangible asset ratios (tang) may be mispriced due to the market's inability to correctly value novel, intangible-driven business models.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RDAbility"},
        {"weight": -1.0, "primitive": "AgeIPO"},
        {"weight": -0.5, "primitive": "tang"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.74,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Unexpected Cash Productivity with Idiosyncratic Volatility",
    "mechanism": "Stocks with positive cash productivity (CashProd) but abnormally high idiosyncratic volatility (IdioVol3F), particularly when realized volatility (RealizedVol) is low, may be systematically underappreciated due to the masking effect of noise on fundamental improvement.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CashProd"},
        {"weight": 1.0, "primitive": "IdioVol3F"},
        {"weight": -0.5, "primitive": "RealizedVol"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "IdioVol3F", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.57,
    "expected_decay_half_life_months": 14
  },
  {
    "name": "Deferred Tax Signaling in Asset Light Firms",
    "mechanism": "Growth in deferred tax liabilities (ChTax) combined with low tangibility (tang) and strong asset turnover (ChAssetTurnover) may signal earnings management among asset-light firms, which the market may underappreciate, particularly in up markets.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ChTax"},
        {"weight": -0.5, "primitive": "tang"},
        {"weight": 1.0, "primitive": "ChAssetTurnover"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "correlation", "primitive": "ChTax", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 16
  },
  {
    "name": "Real Estate Holdings and Credit Quality in Down Markets",
    "mechanism": "Companies with substantial real estate assets (realestate) and low credit risk downgrades (CredRatDG) may provide downside protection and hidden collateral value, especially when market returns have recently been negative.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "realestate"},
        {"weight": -0.5, "primitive": "CredRatDG"},
        {"weight": 1.0, "primitive": "Cash"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.51,
    "expected_decay_half_life_months": 26
  }
]}
